import{z as n,x as D,o as e,c as o,q as s,j as r,D as E,d as B,s as i,S as l,b as A}from"./chunks/framework.C8m1ZpeB.js";const m=JSON.parse('{"title":"ASID / PCID","description":"","frontmatter":{"title":"ASID / PCID","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/asid-pcid.md","filePath":"cs/asid-pcid.md","lastUpdated":1791413859000}'),d={name:"cs/asid-pcid.md"};function p(I,a,P,C,S,T){const t=D("Mermaid");return e(),o("div",null,[a[2]||(a[2]=s('<h1 id="asid-pcid" tabindex="-1">ASID / PCID <a class="header-anchor" href="#asid-pcid" aria-label="Permalink to &quot;ASID / PCID&quot;">​</a></h1><div class="epigraph"><p>TLB 条目带上地址空间编号，切进程不必把所有翻译丢掉；编号用尽或内核改了页表，仍要按地址作废。</p><footer>—— 据 Hennessy and Patterson, Computer Architecture: A Quantitative Approach 整理</footer></div><p><a href="/cs/hw-page-walk">上一课</a>让 MMU 自己走表填 TLB。<a href="/cs/tlb-translate">TLB</a> 已点名「切换要刷或用 ASID」，未把标签写成机制。本课不重讲游走状态机。缺口是：TLB 存的是 VPN→PPN，而各进程的 VPN 重叠；不带空间标识就会把别人的翻译用在当前 <code>satp</code> 上。本课只钉 ASID/PCID：查找时标签匹配须含空间号。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>进程切换改根页表指针。若 TLB 仍热着旧进程的 VPN，下一条用户 load 会命中错误 PPN，保护被绕过。最简办法：切换时全部无效。工作集翻译全变成强制缺失，IPC 掉一截。缺口不是更大的 TLB，而是<strong>每条 TLB 项存 ASID（ARM/RISC-V）或 PCID（x86），查找用「当前空间号 + VPN」</strong>。</p><p>内核全局映射（对所有进程同 PPN 的窗口）可用全局位，切换仍保留那些项。本课承认这一位，不把具体 CSR 编号当正文。</p><p><span class="marginnote">ASID 位宽有限。操作系统维护 PID→ASID 的分配，用尽则回收并作废该号下的项。</span></p><p><span class="marginnote">直觉类比：TLB 像门卫手里的访客登记条，上面只写着「房间号 → 找谁」；两栋楼的房间号都从 1 编起，登记条不标楼号就会把人放进错楼。ASID 就是登记条上多写的那一栏「楼号」，查找时楼号房间号都得对上。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>当前 ASID 写在翻译控制寄存器里，与根指针一起切换。TLB 命中条件：有效、VPN 匹配、ASID 匹配（或全局）。硬件游走填项时写入当时的 ASID。内核改某一进程页表：对该 ASID 做地址范围无效，而不是全芯片全刷。</p>',10)),(e(),r(l,null,{default:E(()=>[i(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20VA%5B%22VPN%20%2B%20%E5%BD%93%E5%89%8D%20ASID%22%5D%20--%3E%20TLB%5B%22TLB%20%E6%A0%87%E7%AD%BE%E6%AF%94%E8%BE%83%22%5D%0A%20%20TLB%20--%3E%7C%22%E5%91%BD%E4%B8%AD%22%7C%20PPN%5B%22%E7%94%A8%E8%AF%A5%20PPN%22%5D%0A%20%20TLB%20--%3E%7C%22%E7%BC%BA%22%7C%20WALK%5B%22%E6%B8%B8%E8%B5%B0%EF%BC%8C%E5%A1%AB%E9%A1%B9%E6%97%B6%E5%86%99%E5%85%A5%20ASID%22%5D%0A%20%20SW%5B%22%E5%88%87%E8%BF%9B%E7%A8%8B%22%5D%20--%3E%20KEEP%5B%22%E4%B8%8D%E5%90%8C%20ASID%20%E7%9A%84%E9%A1%B9%E5%8F%AF%E4%BF%9D%E7%95%99%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[B(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=A("p",null,"PCID 与 ASID 同一思想：x86 在 CR3 里带 PCID，INVPCID 按编号作废。本课不绑指令助记符。",-1)),a[4]||(a[4]=A("p",null,[A("span",{class:"marginnote"},"给「编号有限」一个数：ASID 常见实现有 8 到 16 位，16 位时最多 65536 个编号。系统里进程数远超它时，操作系统就得复用旧号——把某号分给新进程前，必须先把该号下所有旧翻译作废，否则新进程会捡到别人的映射。")],-1)),a[5]||(a[5]=A("h2",{id:"机制",tabindex:"-1"},[B("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=A("p",null,"切换的 TLB 强制缺失从「整本工作集」变成「冷 ASID 或容量不够」。这是局部性在翻译缓存上的版本：进程来回切时，两边的热页翻译可以同时住在 TLB 里，只要编号不同。",-1)),a[7]||(a[7]=A("p",null,"内核改了页表之后，作废范围怎么圈才既安全又不误伤？",-1)),(e(),r(l,null,{default:E(()=>[i(t,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22%E5%86%85%E6%A0%B8%E6%94%B9%E4%BA%86%E6%9F%90%E8%BF%9B%E7%A8%8B%E7%9A%84%E9%A1%B5%E8%A1%A8%22%5D%20--%3E%20Q%7B%22%E5%93%AA%E4%BA%9B%20TLB%20%E9%A1%B9%E5%8F%AF%E8%83%BD%E8%A2%AB%E6%97%A7%E8%A1%A8%E5%A1%AB%E8%BF%87%22%7D%0A%20%20Q%20--%3E%7C%22%E8%AF%A5%20ASID%20%E5%90%8D%E4%B8%8B%E7%9A%84%E9%A1%B9%22%7C%20I1%5B%22%E6%8C%89%20ASID%20%E4%B8%8E%E5%9C%B0%E5%9D%80%E8%8C%83%E5%9B%B4%E4%BD%9C%E5%BA%9F%22%5D%0A%20%20Q%20--%3E%7C%22%E6%A0%87%E4%BA%86%E5%85%A8%E5%B1%80%E4%BD%8D%E7%9A%84%E9%A1%B9%22%7C%20I2%5B%22%E6%98%A0%E5%B0%84%E8%8B%A5%E6%9C%AA%E5%8F%98%E5%88%99%E4%BF%9D%E7%95%99%22%5D%0A%20%20Q%20--%3E%7C%22%E5%85%B6%E4%BB%96%20ASID%20%E7%9A%84%E9%A1%B9%22%7C%20K%5B%22%E4%B8%8E%E6%9C%AC%E6%AC%A1%E6%94%B9%E5%8A%A8%E6%97%A0%E5%85%B3%20%E5%8E%9F%E6%A0%B7%E4%BF%9D%E7%95%99%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[B(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=s('<p><span class="marginnote">常见误区：初学者容易以为「切进程就得把 TLB 刷干净」。带 ASID 后，只有编号冷了或容量装不下才强制缺失；两个热进程来回切换，各自的翻译都能留着——这正是高频 IPC 往返还能快的一个隐形前提。</span></p><p>安全：忘记改 ASID 或全局位标错，会串空间。作废必须覆盖「该项可能被旧表填过」的集合。与 cache 包含性无关：TLB 不是数据层次的一层，但内核改页表后两边都可能要动——数据 cache 用物理标签则不必因切进程而全刷数据 cache。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入虚拟机的 vPID/VMID 二层标签，不讨论 TLB 射击的核间 IPI。一致性问题下一课针对的是数据副本，不是翻译标签；但 DMA 与多核会让「当前值在哪」变成主缺口。也不把 ASID 当成用户可编程的沙箱：用户改不了自己的 ASID。</p><p>后课默认：切进程保留带编号的 TLB 项；改页表则按 ASID 作废。同一物理行的多份 cache 副本如何一致，是下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>TLB 查找 = VPN + ASID/PCID（或全局位）。</li><li>切换不必全刷；编号回收与改表仍要定向作废。</li><li>数据副本的一致性是下一课，不是翻译标签。</li><li>出处：Hennessy and Patterson, <em>CA:AQA</em> TLB 与进程切换。</li></ul>',7))])}const h=n(d,[["render",p]]);export{m as __pageData,h as default};
